def magic_square_test(matrix):
    n = len(matrix)
    if n == 0:
        return False

    # Check if all rows have the same length
    for row in matrix:
        if len(row) != n:
            return False

    # Calculate the magic constant (sum of first row)
    magic_sum = sum(matrix[0])

    # Check all rows
    for i in range(n):
        if sum(matrix[i]) != magic_sum:
            return False

    # Check all columns
    for j in range(n):
        col_sum = sum(matrix[i][j] for i in range(n))
        if col_sum != magic_sum:
            return False

    # Check main diagonal
    main_diag_sum = sum(matrix[i][i] for i in range(n))
    if main_diag_sum != magic_sum:
        return False

    # Check anti-diagonal
    anti_diag_sum = sum(matrix[i][n - 1 - i] for i in range(n))
    if anti_diag_sum != magic_sum:
        return False

    # Check that all numbers are unique and in the range 1 to n^2
    numbers = [matrix[i][j] for i in range(n) for j in range(n)]
    if len(set(numbers)) != n * n:
        return False
    if min(numbers) < 1 or max(numbers) > n * n:
        return False

    return True
