def find_solution(a, b, n):
    """
    Find integers x and y such that ax + by = n.
    Returns (x, y) if a solution exists, otherwise None.
    """
    from math import gcd

    # Handle edge cases
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return None

    if a == 0:
        if n % b == 0:
            return (0, n // b)
        else:
            return None

    if b == 0:
        if n % a == 0:
            return (n // a, 0)
        else:
            return None

    # Check if solution exists: gcd(a, b) must divide n
    g = gcd(a, b)
    if n % g != 0:
        return None

    # Use extended Euclidean algorithm to find x0, y0 such that a*x0 + b*y0 = g
    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            g, x1, y1 = extended_gcd(b, a % b)
            return (g, y1, x1 - (a // b) * y1)

    g, x0, y0 = extended_gcd(a, b)

    # Scale the solution: since a*x0 + b*y0 = g, multiply by n/g
    factor = n // g
    x = x0 * factor
    y = y0 * factor

    return (x, y)
```

