def is_majority(arr, n, element):
    # Find the first occurrence of element using binary search
    def lower_bound(arr, n, target):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    # Find the last occurrence of element using binary search
    def upper_bound(arr, n, target):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    first = lower_bound(arr, n, element)
    last = upper_bound(arr, n, element)
    count = last - first
    return count > n // 2
