    if n == 0:
        return 0

    # inc[i] = maximum sum of increasing subsequence ending at i
    inc = [0] * n
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # dec[i] = maximum sum of decreasing subsequence starting at i
    dec = [0] * n
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # The maximum bitonic sum is max(inc[i] + dec[i] - arr[i]) for all i
    # We subtract arr[i] because it's counted in both inc[i] and dec[i]
    result = 0
    for i in range(n):
        result = max(result, inc[i] + dec[i] - arr[i])

    return result
