        return {}

    words = test.split()
    if not words:
        return {}

    # Count occurrences
    counts = {}
    for word in words:
        if word:
            counts[word] = counts.get(word, 0) + 1

    if not counts:
        return {}

    # Find the maximum count
    max_count = max(counts.values())

    # Return all letters with the maximum count
